import time
import numpy as np
import matplotlib.pyplot as plt

def linear(n): return sum(range(n))
def quadratic(n): return sum(i*j for i in range(n) for j in range(n))
sizes=np.array([100,200,400,800]);times={"linear":[],"quadratic":[]}
for n in sizes:
    for name,fn in [("linear",linear),("quadratic",quadratic)]:
        t=time.perf_counter();fn(int(n));times[name].append(time.perf_counter()-t)
for name,vals in times.items():
    slope=np.polyfit(np.log(sizes),np.log(vals),1)[0];print(name,"empirical log-log slope",round(slope,2))
    plt.loglog(sizes,vals,"o-",label=name)
plt.xlabel("n");plt.ylabel("seconds");plt.legend();plt.show()
